mapper.select:

WHERE del_flag = '0'
  AND application_id = #{applicationId}
ORDER BY transition_time ASC, log_id ASC


WHERE del_flag = '0'

    AND transition_time BETWEEN #{startDate} AND #{endDate}


    AND action = #{action}

ORDER BY transition_time DESC


WHERE del_flag = '0'
  AND operator_id = #{operatorId}

    AND transition_time BETWEEN #{startDate} AND #{endDate}

ORDER BY transition_time DESC

SELECT COUNT(*) as total_reviews, AVG(duration) as avg_duration_ms, ROUND(AVG(duration) / 1000, 2) as avg_duration_seconds, MIN(duration) as min_duration_ms, MAX(duration) as max_duration_ms, COUNT(DISTINCT operator_id) as reviewer_count, COUNT(DISTINCT application_id) as application_count FROM des_application_state_log WHERE del_flag = '0'
AND transition_time BETWEEN #{startDate} AND #{endDate}
AND action = #{action}

SELECT COALESCE(AVG(duration), 0)
FROM des_application_state_log
WHERE del_flag = '0'
  AND action = #{action}

    AND transition_time BETWEEN #{startDate} AND #{endDate}

SELECT COUNT(*)
FROM des_application_state_log
WHERE del_flag = '0'
  AND action = #{action}

    AND transition_time BETWEEN #{startDate} AND #{endDate}

SELECT operator_id, operator_name, COUNT(*) as review_count, AVG(duration) as avg_duration_ms, MIN(transition_time) as first_review_time, MAX(transition_time) as last_review_time, SUM(CASE WHEN to_status IN ('1', '3') THEN 1 ELSE 0 END) as approved_count, SUM(CASE WHEN to_status IN ('2', '4') THEN 1 ELSE 0 END) as rejected_count FROM des_application_state_log WHERE del_flag = '0' AND action IN ('ADMIN_REVIEW', 'ENTERPRISE_REVIEW')
AND transition_time BETWEEN #{startDate} AND #{endDate}
GROUP BY operator_id, operator_name ORDER BY review_count DESC

SELECT DATE(transition_time) as review_date, COUNT(*) as total_reviews, SUM(CASE WHEN action = 'ADMIN_REVIEW' THEN 1 ELSE 0 END) as admin_reviews, SUM(CASE WHEN action = 'ENTERPRISE_REVIEW' THEN 1 ELSE 0 END) as enterprise_reviews, SUM(CASE WHEN to_status IN ('1', '3') THEN 1 ELSE 0 END) as approved_count, AVG(duration) as avg_duration_ms FROM des_application_state_log WHERE del_flag = '0' AND action IN ('ADMIN_REVIEW', 'ENTERPRISE_REVIEW')
AND transition_time BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(transition_time) ORDER BY review_date DESC
